<script lang="ts">
 import {basicFleetBlocker,basicFleetCost} from './basic-fleet-action';
 import {basicActions} from './manifest';
 import {fleetBuildPreview,fleetLocation} from './fleet-preview';
 import type {PublicSetup} from './setup';

 let {game,busy,allowed,space=$bindable(0),compact=false}:{game:PublicSetup;busy:boolean;allowed:boolean;space:number;compact?:boolean}=$props();
 let build=$state(true),destination=$state('sol');
 const actor=$derived(game.players.find(p=>p.position===game.activePosition)!);
 const preview=$derived(fleetBuildPreview(game,actor.position,{kind:'ship',level:1,cube:'population'},destination));
 const blocker=$derived(basicFleetBlocker(game,space,build,destination));
 export function selection(){return {move:{kind:'build-jump' as const,space,build,destination},reason:blocker,summary:compact?`${basicFleetCost(game,space)} Ore · ${build?'1 Population → level 1':'no ship built'} · up to 2 jumps.`:`Space ${space+1} · pay ${basicFleetCost(game,space)} Ore · ${build?`1 Population → level 1 at ${fleetLocation(game,destination)}`:'no ship built'} · then up to 2 jumps.`};}
</script>
<section class="basic-fleet-plan" class:compact aria-label="Basic shipbuilding plan">
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (Named bounded shipbuilding region supports keyboard scrolling.) -->
 <div class="plan-scroll" role="region" tabindex="0" aria-label="Shipbuilding spaces, cube and permitted yards">
 <div class="source-plaque"><span class="eyebrow">Basic Spacefaring · {game.count}-player {game.count===4?'board':'overlay'}</span><p>Build is optional · then up to 2 jumps.</p></div>
 <fieldset><legend>Printed Action space</legend><div class="spaces">{#each basicActions.find(a=>a.id==='build-jump')!.spaces[game.count] as cost,index}{@const occupant=game.players.find(p=>p.actionLocation===`build-jump:${index}`)}<label class:selected={space===index}><input type="radio" disabled={!allowed||busy} name="basic-build-space" value={index} bind:group={space}/><span>Space {index+1}<small>{occupant?`Occupied by ${occupant.name}`:cost?`+${cost} Ore`:'No Ore surcharge'}</small></span></label>{/each}</div></fieldset>
 <div class="construction-controls"><label class="build-option"><input type="checkbox" disabled={!allowed||busy} bind:checked={build}/><span><strong>Build one level-1 ship</strong><small>{actor.population} available Population · not Supply</small></span></label>{#if build&&preview.locations.length>1}<label class="yard-select">Build location · Sol or your outpost<select aria-label="Permitted build location" bind:value={destination} disabled={!allowed||busy}>{#each preview.locations as id}<option value={id}>{fleetLocation(game,id)}</option>{/each}</select></label>{/if}</div>
 {#if build}<div class="build-instrument">{#if compact}<div class="cube" aria-hidden="true">♟</div><div><strong>1 Population → level 1</strong><span>{actor.population} → {Math.max(0,actor.population-1)} Population</span></div><div class="cube" aria-hidden="true">1</div><small>{preview.power.title} · power {preview.power.powers.find(p=>p.position===actor.position)?.before} → {preview.power.powers.find(p=>p.position===actor.position)?.after}{preview.power.controllable?' · control retained':' · no control'}</small>{:else}<div class="conversion"><div class="resource-object"><span class="cube population-cube" aria-hidden="true">♟</span><div><small>Source cube</small><strong>Population</strong><span>{actor.population} → {Math.max(0,actor.population-1)} available</span></div></div><span class="arrow" aria-hidden="true">→</span><div class="resource-object"><span class="cube" aria-hidden="true">1</span><div><small>New ship</small><strong>Level 1</strong><span>{fleetLocation(game,destination)}</span></div></div></div><div class="destination-power" aria-live="polite"><strong>{preview.power.title}</strong><span>Fleet power <b>{preview.power.powers.find(p=>p.position===actor.position)?.before} → {preview.power.powers.find(p=>p.position===actor.position)?.after}</b></span><small>{preview.power.controllable?'Your shipyard control is retained.':'Sol cannot be controlled.'}</small></div>{/if}</div>{:else}<p class="no-build">Keep your Population. Use your existing ships for the subsequent jump choice; unused movement is optional.</p>{/if}
 </div>
 {#if build&&preview.locations.length>1}<p class="scroll-cue">Build location and fleet power · scroll for all details</p>{/if}
</section>
<style>
