teY(-2px) rotate(45deg)}input:disabled{cursor:default;opacity:.55}small{display:block;font-size:12px;line-height:1.35;margin-top:3px;color:#d1d0b7}.build-option strong{display:block;font-size:15px}.build-instrument{display:grid;gap:12px;padding:14px 16px;background:linear-gradient(135deg,#16353b,#0d242b);border:1px solid #9e895b;border-radius:9px;box-shadow:inset 0 0 0 3px #baa36a0d,0 3px #142829}.conversion{display:grid;grid-template-columns:minmax(0,1fr) 24px minmax(0,1fr);gap:12px;align-items:center}.resource-object{display:flex;align-items:center;gap:13px;min-width:0}.resource-object>div{min-width:0}.resource-object small{margin:0;font-size:11px;text-transform:uppercase;letter-spacing:.07em}.resource-object strong{display:block;font:600 25px 'Cormorant Garamond',serif;line-height:1.2;margin:3px 0}.resource-object div>span{min-height:2.7em;font-size:13px;line-height:1.35;display:block}.cube{display:inline-grid;place-items:center;flex:none;width:46px;height:46px;background:linear-gradient(130deg,#5abeb9,#1b6667);border:1px solid #8ae0d2;border-radius:8px;box-shadow:inset -6px -6px #123e4566,inset 4px 4px #b1ffdf44,2px 4px #153b3e;color:#fff3cc;font:600 33px 'Cormorant Garamond',serif}.population-cube{background:linear-gradient(130deg,#e5d8b7,#b7a17a);border-color:#957b4e;color:#263e38;box-shadow:inset -5px -5px #826d4d44,2px 4px #756349}.arrow{font-size:27px;text-align:center}.destination-power{display:grid;grid-template-columns:1fr auto;gap:3px 15px;border-top:1px solid #b69b6255;padding-top:10px}.destination-power strong{font-size:14px}.destination-power>span{font-size:13px}.destination-power b{font:600 23px 'Cormorant Garamond',serif;margin-left:8px}.destination-power small{grid-column:1/-1;margin:0}input:focus-visible{outline:3px solid #71eee7;outline-offset:0;border-radius:6px}label:has(input:focus-visible){outline:2px solid #71eee7;outline-offset:2px}.no-build{padding:14px;border:1px solid #ae956255;border-radius:7px;font-size:14px;line-height:1.4;margin:0}
@container(max-width:400px){.source-plaque{padding:7px 10px}.source-plaque p{font-size:12px}.build-instrument{gap:9px;padding:12px}.conversion{gap:7px;grid-template-columns:minmax(0,1fr) 18px minmax(0,1fr)}.resource-object{gap:8px}.resource-object strong{font-size:22px}.resource-object div>span{font-size:12px}.cube{width:40px;height:40px;font-size:29px}.resource-object small{font-size:10px}.destination-power{gap:3px 8px}.destination-power b{font-size:21px}.spaces label{font-size:13px}}
@media(min-width:761px){.plan-scroll{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.source-plaque,.build-instrument,.no-build{grid-column:1/-1}.construction-controls{align-self:stretch}.build-instrument{grid-row:3}}
.compact .plan-scroll{gap:6px;grid-template-columns:minmax(0,1fr) minmax(0,1.3fr)}.compact .plan-scroll>.source-plaque{display:none}.compact .plan-scroll>fieldset:not(.yard-picker){grid-column:1;grid-row:1/span 2;padding:6px}.compact .spaces{grid-template-columns:1fr;gap:5px}.compact .spaces label{min-height:44px;padding:4px}.compact .construction-controls{grid-column:2;grid-row:1}.compact .build-option{padding:6px;min-height:44px;gap:8px}.compact .build-option strong{font-size:14px}.compact .build-option small{font-size:12px;line-height:1.25}.compact .build-instrument{grid-column:2;grid-row:2;grid-template-columns:40px minmax(0,1fr) 40px;gap:5px;padding:8px}.compact .build-instrument strong{display:block;font:600 16px/1.15 'Cormorant Garamond',serif}.compact .build-instrument div span{display:block;font-size:12px;margin-top:4px}.compact .cube{width:40px;height:40px}.compact .build-instrument small{grid-column:1/-1;font-size:12px;line-height:1.2;margin:0}
